#!/usr/bin/env node
/**
 * Generate src/lib/actions/_generated/index.ts — the side-effect import
 * manifest that populates the action registry.
 *
 * Why this exists: 14 squads work in parallel under
 * src/lib/actions/{tools,intents,workspace}/. If they all had to PR
 * edits to a single hand-maintained register-all.ts, every squad PR
 * would conflict on that file. By generating the manifest, squads only
 * touch their own files; the next dev/build run picks them up
 * automatically.
 *
 * Runs as pre{dev,build,test} so the generated file is always fresh
 * before any code that imports the registry executes.
 *
 * Idempotent — re-runs produce byte-identical output (sorted glob,
 * stable timestamps elided).
 */

import { readdirSync, statSync, writeFileSync, mkdirSync, existsSync, readFileSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const ROOT = join(__dirname, "..");

const ACTIONS_DIR = join(ROOT, "src", "lib", "actions");
const OUT_DIR = join(ACTIONS_DIR, "_generated");
const OUT_FILE = join(OUT_DIR, "index.ts");

// Directories whose .ts files are auto-imported into the registry.
// Order is deterministic but irrelevant (registry de-dupes by id) —
// the array order only affects the order they appear in the manifest.
const SCAN_DIRS = ["workspace", "tools", "intents"];

// Files that are NOT action modules (helpers, types, the directory's
// own index file, generated artifacts). Anything matching is skipped.
const SKIP_PATTERNS = [
  /\.test\.ts$/,
  /\.d\.ts$/,
  /\/_/, // any path segment starting with underscore (e.g. _generated, _shared)
  /\/index\.ts$/, // dir index files re-export; importing them re-runs side effects but pulls in extra symbols
];

/** Recursively collect .ts files under `dir`, returning POSIX-style
 *  paths relative to ACTIONS_DIR. */
function walk(dir) {
  const out = [];
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) {
      out.push(...walk(full));
    } else if (st.isFile() && name.endsWith(".ts")) {
      out.push(full);
    }
  }
  return out;
}

function toImportPath(abs) {
  // From _generated/index.ts the relative path back to a sibling module
  // under ../{tools,intents,workspace}/... — strip extension; use POSIX
  // separators so Windows + Linux both produce identical output.
  const rel = relative(OUT_DIR, abs).replaceAll("\\", "/");
  return rel.replace(/\.ts$/, "");
}

function shouldSkip(absPath) {
  const norm = absPath.replaceAll("\\", "/");
  return SKIP_PATTERNS.some((re) => re.test(norm));
}

const collected = [];
for (const dirName of SCAN_DIRS) {
  const dir = join(ACTIONS_DIR, dirName);
  const files = walk(dir).filter((f) => !shouldSkip(f));
  // For workspace/, we keep index.ts because that's where defineCrudActions
  // calls live. Re-include if the only file in the dir is index.ts.
  if (dirName === "workspace") {
    const idx = join(dir, "index.ts");
    const scalars = join(dir, "scalars.ts");
    if (existsSync(idx) && !files.includes(idx)) files.push(idx);
    if (existsSync(scalars) && !files.includes(scalars)) files.push(scalars);
  }
  files.sort(); // deterministic order
  for (const f of files) collected.push(f);
}

const imports = collected.map((f) => `import "${toImportPath(f)}";`).join("\n");

const header = `/**
 * AUTO-GENERATED — DO NOT EDIT BY HAND.
 *
 * Regenerated by \`scripts/generate-action-registry.mjs\` on every
 * pre{dev,build,test} step. To add a new action module, drop a .ts file
 * under src/lib/actions/{tools,intents,workspace}/ and re-run dev/build.
 *
 * Source files included:
${collected.map((f) => " *   - " + relative(ROOT, f).replaceAll("\\", "/")).join("\n")}
 */
`;

const body = `${header}
${imports}

export {};
`;

mkdirSync(OUT_DIR, { recursive: true });

// Idempotency: only write if the content actually changed. Avoids
// thrashing file mtime which can trigger Next.js dev recompiles even
// when nothing changed (the script runs on `predev` and `next dev`
// watches the file).
let prior = "";
if (existsSync(OUT_FILE)) {
  prior = readFileSync(OUT_FILE, "utf-8");
}
if (prior !== body) {
  writeFileSync(OUT_FILE, body, "utf-8");
  console.log(
    `[generate-action-registry] wrote ${relative(ROOT, OUT_FILE)} (${collected.length} modules)`
  );
} else {
  console.log(`[generate-action-registry] up to date (${collected.length} modules)`);
}
